fn benchmark_tensor_add() {
  let a = Tensor::random(&[1024, 1024]);  // Allocation + initialization
  let b = Tensor::random(&[1024, 1024]);  // Allocation + initialization

  let start = Instant::now();
  for _ in 0..1000 {
    let c = a.add(&b);  // Copies result into new allocation
  }
  println!("{:?}", start.elapsed());
  // Measures: allocation + copy + addition + deallocation
  // Cannot determine if bottleneck is memory or arithmetic
}

good_example:
fn benchmark_tensor_add_zero_copy() {
  let a = Tensor::random(&[1024, 1024]);
  let b = Tensor::random(&[1024, 1024]);
  let mut c = Tensor::uninitialized(&[1024, 1024]);  // Pre-allocated output

  // Warm up: ensure tensors are in cache
  c.copy_from(&a);

  let start = Instant::now();
  for _ in 0..1000 {
    a.add_into(&b, &mut c);  // Zero-copy: writes into pre-allocated buffer
  }
  println!("{:?}", start.elapsed());
  // Measures: only the addition micro-execution
  // Data movement cost is amortized in setup
}

// Separate benchmark for data movement overhead:
fn benchmark_allocation_overhead() {
  let start = Instant::now();
  for _ in 0..1000 {
    let _ = Tensor::uninitialized(&[1024, 1024]);
  }
  println!("Allocation: {:?}", start.elapsed());
}
